```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Dune Line — Overnight Trans-Desert Rail to Vespera</title>
  <style>
    :root {
      --bg-void: #07080d;
      --bg-deep: #0c0e17;
      --bg-surface: #131624;
      --bg-elevated: #191d2f;
      --bg-glass: rgba(15, 18, 30, 0.78);

      --text-primary: #f5ecdf;
      --text-secondary: #b7b0a8;
      --text-muted: #7c7985;

      --sand-gold: #e6b877;
      --sand-bright: #f7d59c;
      --sand-deep: #b87e3b;
      --neon-cyan: #38f2d1;
      --neon-rose: #ff3f82;
      --neon-violet: #8c52ff;

      --border-subtle: rgba(245, 236, 223, 0.09);
      --border-strong: rgba(230, 184, 119, 0.28);
      --border-cyan: rgba(56, 242, 209, 0.28);

      --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      --font-serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;
      --font-mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Monaco, Consolas, monospace;

      --radius-sm: 6px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-pill: 999px;

      --container: 1200px;
      --shadow-card: 0 24px 60px rgba(0, 0, 0, 0.45);
      --shadow-glow-gold: 0 0 36px rgba(230, 184, 119, 0.16);
      --shadow-glow-cyan: 0 0 32px rgba(56, 242, 209, 0.15);
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      background-color: var(--bg-void);
      color: var(--text-primary);
      font-family: var(--font-sans);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      background-color: var(--bg-void);
      background-image:
        radial-gradient(ellipse 70% 45% at 15% 0%, rgba(230, 184, 119, 0.08), transparent 65%),
        radial-gradient(ellipse 65% 50% at 88% 8%, rgba(56, 242, 209, 0.07), transparent 60%),
        radial-gradient(ellipse 55% 40% at 75% 45%, rgba(255, 63, 130, 0.045), transparent 60%);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font: inherit;
      color: inherit;
      background: none;
      border: none;
      cursor: pointer;
    }

    .container {
      width: 100%;
      max-width: var(--container);
      margin: 0 auto;
      padding: 0 32px;
    }

    /* Typography Helpers */
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      color: var(--sand-gold);
    }

    .eyebrow-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--neon-cyan);
      box-shadow: 0 0 10px var(--neon-cyan);
      flex-shrink: 0;
    }

    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      gap: 32px;
      margin-bottom: 52px;
    }

    .section-title {
      font-size: clamp(2rem, 3.2vw, 2.85rem);
      font-weight: 600;
      letter-spacing: -0.025em;
      line-height: 1.12;
      margin-top: 14px;
      color: var(--text-primary);
    }

    .section-title em {
      font-family: var(--font-serif);
      font-style: italic;
      font-weight: 400;
      color: var(--sand-gold);
    }

    .section-desc {
      max-width: 440px;
      color: var(--text-secondary);
      font-size: 0.98rem;
      line-height: 1.65;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 13px 24px;
      border-radius: var(--radius-pill);
      font-size: 0.9rem;
      font-weight: 500;
      letter-spacing: 0.01em;
      transition: transform 0.22s ease, box-shadow 0.22s ease, background 0.22s ease, border-color 0.22s ease;
      white-space: nowrap;
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--sand-bright) 0%, var(--sand-gold) 55%, #cf9549 100%);
      color: #120d06;
      font-weight: 600;
      box-shadow: 0 8px 26px rgba(230, 184, 119, 0.24);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 34px rgba(230, 184, 119, 0.36);
    }

    .btn-secondary {
      background: rgba(245, 236, 223, 0.04);
      border: 1px solid var(--border-subtle);
      color: var(--text-primary);
    }

    .btn-secondary:hover {
      border-color: rgba(230, 184, 119, 0.45);
      background: rgba(230, 184, 119, 0.08);
      transform: translateY(-1px);
    }

    .btn-neon {
      background: rgba(56, 242, 209, 0.1);
      border: 1px solid rgba(56, 242, 209, 0.42);
      color: var(--neon-cyan);
    }

    .btn-neon:hover {
      background: rgba(56, 242, 209, 0.18);
      box-shadow: 0 0 24px rgba(56, 242, 209, 0.22);
      transform: translateY(-1px);
    }

    /* Navigation Bar */
    .navbar {
      position: sticky;
      top: 0;
      z-index: 100;
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      background: rgba(7, 8, 13, 0.78);
      border-bottom: 1px solid var(--border-subtle);
    }

    .nav-inner {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 12px;
    }

    .brand-mark {
      width: 34px;
      height: 34px;
      flex-shrink: 0;
    }

    .brand-text {
      display: flex;
      flex-direction: column;
      line-height: 1;
    }

    .brand-name {
      font-size: 0.96rem;
      font-weight: 700;
      letter-spacing: 0.24em;
      text-transform: uppercase;
      color: var(--text-primary);
    }

    .brand-sub {
      font-family: var(--font-mono);
      font-size: 0.62rem;
      letter-spacing: 0.16em;
      color: var(--text-muted);
      margin-top: 4px;
      text-transform: uppercase;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 34px;
      list-style: none;
    }

    .nav-links a {
      font-size: 0.88rem;
      color: var(--text-secondary);
      transition: color 0.2s ease;
      position: relative;
      padding: 4px 0;
    }

    .nav-links a::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: -2px;
      width: 0;
      height: 1px;
      background: var(--sand-gold);
      transition: width 0.24s ease;
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .nav-links a:hover::after {
      width: 100%;
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .nav-status {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 7px 12px;
      border-radius: var(--radius-pill);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--border-subtle);
      font-family: var(--font-mono);
      font-size: 0.7rem;
      letter-spacing: 0.08em;
      color: var(--text-secondary);
    }

    .nav-status strong {
      color: var(--neon-cyan);
      font-weight: 600;
    }

    .pulse-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--neon-cyan);
      box-shadow: 0 0 10px var(--neon-cyan);
      animation: pulseGlow 2.4s ease-in-out infinite;
    }

    .nav-toggle {
      display: none;
      width: 40px;
      height: 40px;
      border-radius: 10px;
      border: 1px solid var(--border-subtle);
      align-items: center;
      justify-content: center;
    }

    /* Hero Section */
    .hero {
      padding: 56px 0 88px;
      position: relative;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
      gap: 44px;
      align-items: center;
    }

    .hero-copy {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 7px 14px;
      border-radius: var(--radius-pill);
      background: rgba(230, 184, 119, 0.08);
      border: 1px solid rgba(230, 184, 119, 0.25);
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--sand-gold);
      margin-bottom: 24px;
    }

    .hero-title {
      font-size: clamp(2.65rem, 4.3vw, 3.85rem);
      font-weight: 600;
      line-height: 1.04;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      margin-bottom: 22px;
    }

    .hero-title .serif-accent {
      display: block;
      font-family: var(--font-serif);
      font-style: italic;
      font-weight: 400;
      background: linear-gradient(95deg, var(--sand-bright) 0%, var(--neon-rose) 58%, var(--neon-cyan) 100%);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      padding-bottom: 4px;
    }

    .hero-lead {
      font-size: 1.05rem;
      line-height: 1.68;
      color: var(--text-secondary);
      max-width: 460px;
      margin-bottom: 32px;
    }

    .hero-ctas {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-bottom: 40px;
    }

    .hero-metrics {
      width: 100%;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      padding-top: 26px;
      border-top: 1px solid var(--border-subtle);
    }

    .metric-val {
      font-family: var(--font-mono);
      font-size: 1.25rem;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: -0.02em;
    }

    .metric-val span {
      font-size: 0.78rem;
      color: var(--sand-gold);
      margin-left: 2px;
    }

    .metric-label {
      font-size: 0.76rem;
      color: var(--text-muted);
      margin-top: 4px;
      letter-spacing: 0.02em;
    }

    /* Hero Artwork Frame */
    .hero-visual {
      position: relative;
    }

    .artwork-frame {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid rgba(245, 236, 223, 0.14);
      background: #0a0b15;
      box-shadow:
        0 32px 80px rgba(0, 0, 0, 0.65),
        0 0 0 1px rgba(230, 184, 119, 0.08) inset;
    }

    .artwork-svg {
      display: block;
      width: 100%;
      height: auto;
    }

    .telemetry-bar {
      position: absolute;
      left: 18px;
      right: 18px;
      bottom: 18px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      padding: 12px 16px;
      border-radius: 12px;
      background: rgba(9, 11, 20, 0.78);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border: 1px solid rgba(245, 236, 223, 0.12);
      font-family: var(--font-mono);
      font-size: 0.72rem;
    }

    .telemetry-left {
      display: flex;
      align-items: center;
      gap: 12px;
      color: var(--text-primary);
    }

    .telemetry-tag {
      padding: 3px 8px;
      border-radius: 4px;
      background: rgba(56, 242, 209, 0.14);
      color: var(--neon-cyan);
      font-weight: 600;
      letter-spacing: 0.08em;
    }

    .telemetry-route {
      color: var(--text-secondary);
      letter-spacing: 0.06em;
    }

    .telemetry-route strong {
      color: var(--sand-bright);
      font-weight: 600;
    }

    .telemetry-right {
      color: var(--sand-gold);
      letter-spacing: 0.08em;
      white-space: nowrap;
    }

    /* SVG Animations */
    @keyframes pulseGlow {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.45; transform: scale(0.85); }
    }

    @keyframes twinkle {
      0%, 100% { opacity: 0.25; }
      50% { opacity: 0.95; }
    }

    @keyframes railSweep {
      0% { stroke-dashoffset: 180; opacity: 0.2; }
      40% { opacity: 0.95; }
      100% { stroke-dashoffset: -180; opacity: 0.2; }
    }

    @keyframes beamBreath {
      0%, 100% { opacity: 0.52; }
      50% { opacity: 0.78; }
    }

    .star-a { animation: twinkle 3.6s ease-in-out infinite; }
    .star-b { animation: twinkle 4.8s ease-in-out 1.2s infinite; }
    .star-c { animation: twinkle 2.9s ease-in-out 0.6s infinite; }
    .rail-streak {
      stroke-dasharray: 42 138;
      animation: railSweep 3.4s linear infinite;
    }
    .headlight-beam { animation: beamBreath 4.2s ease-in-out infinite; }

    /* Sections General */
    section.band {
      padding: 96px 0;
      position: relative;
    }

    .band-divider {
      border-top: 1px solid var(--border-subtle);
    }

    /* Feature Highlights */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .feature-card {
      position: relative;
      padding: 32px 30px 34px;
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, rgba(22, 26, 42, 0.85) 0%, rgba(13, 15, 25, 0.92) 100%);
      border: 1px solid var(--border-subtle);
      transition: transform 0.28s ease, border-color 0.28s ease, box-shadow 0.28s ease;
      overflow: hidden;
    }

    .feature-card::before {
      content: "";
      position: absolute;
      inset: 0 0 auto 0;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(230, 184, 119, 0.45), transparent);
      opacity: 0;
      transition: opacity 0.28s ease;
    }

    .feature-card:hover {
      transform: translateY(-5px);
      border-color: rgba(230, 184, 119, 0.3);
      box-shadow: var(--shadow-card);
    }

    .feature-card:hover::before {
      opacity: 1;
    }

    .feature-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 28px;
    }

    .feature-icon-wrap {
      width: 56px;
      height: 56px;
      border-radius: 14px;
      background: rgba(230, 184, 119, 0.08);
      border: 1px solid rgba(230, 184, 119, 0.22);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-card.accent-cyan .feature-icon-wrap {
      background: rgba(56, 242, 209, 0.08);
      border-color: rgba(56, 242, 209, 0.24);
    }

    .feature-card.accent-rose .feature-icon-wrap {
      background: rgba(255, 63, 130, 0.08);
      border-color: rgba(255, 63, 130, 0.24);
    }

    .feature-num {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.16em;
      color: var(--text-muted);
    }

    .feature-title {
      font-size: 1.24rem;
      font-weight: 600;
      letter-spacing: -0.015em;
      margin-bottom: 12px;
      color: var(--text-primary);
    }

    .feature-copy {
      font-size: 0.94rem;
      line-height: 1.68;
      color: var(--text-secondary);
      margin-bottom: 24px;
    }

    .feature-meta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--sand-gold);
    }

    .feature-card.accent-cyan .feature-meta {
      color: var(--neon-cyan);
    }

    .feature-card.accent-rose .feature-meta {
      color: #ff7ba9;
    }

    /* Route Schematic + Timetable */
    .route-schematic {
      margin-bottom: 30px;
      padding: 24px 28px;
      border-radius: var(--radius-lg);
      background: rgba(15, 18, 30, 0.75);
      border: 1px solid var(--border-subtle);
    }

    .schematic-label-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 14px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-muted);
    }

    .schematic-label-row strong {
      color: var(--text-primary);
    }

    .timetable-board {
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, #111422 0%, #0c0e18 100%);
      border: 1px solid rgba(245, 236, 223, 0.12);
      overflow: hidden;
      box-shadow: var(--shadow-card);
    }

    .timetable-head,
    .timetable-row {
      display: grid;
      grid-template-columns: 115px 1.35fr 110px 1.2fr 110px 95px 135px 118px;
      align-items: center;
      gap: 16px;
      padding: 0 28px;
    }

    .timetable-head {
      height: 50px;
      background: rgba(255, 255, 255, 0.025);
      border-bottom: 1px solid var(--border-subtle);
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--text-muted);
    }

    .timetable-row {
      min-height: 82px;
      padding-top: 16px;
      padding-bottom: 16px;
      border-bottom: 1px solid var(--border-subtle);
      transition: background 0.2s ease;
    }

    .timetable-row:last-child {
      border-bottom: none;
    }

    .timetable-row:hover {
      background: rgba(230, 184, 119, 0.045);
    }

    .train-code {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 5px 10px;
      border-radius: 6px;
      background: rgba(230, 184, 119, 0.1);
      border: 1px solid rgba(230, 184, 119, 0.28);
      font-family: var(--font-mono);
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--sand-bright);
      letter-spacing: 0.08em;
      width: fit-content;
    }

    .service-name {
      font-weight: 600;
      font-size: 0.96rem;
      color: var(--text-primary);
    }

    .service-sub {
      display: block;
      font-size: 0.78rem;
      color: var(--text-muted);
      margin-top: 2px;
    }

    .time-cell {
      font-family: var(--font-mono);
      font-size: 1.05rem;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: 0.02em;
    }

    .time-cell small {
      display: block;
      font-size: 0.66rem;
      font-weight: 400;
      color: var(--text-muted);
      letter-spacing: 0.08em;
      margin-top: 2px;
    }

    .time-cell.arrival {
      color: var(--neon-cyan);
    }

    .waypoint-cell {
      font-size: 0.86rem;
      color: var(--text-secondary);
    }

    .waypoint-cell small {
      display: block;
      font-family: var(--font-mono);
      font-size: 0.68rem;
      color: var(--text-muted);
      margin-top: 2px;
    }

    .duration-cell {
      font-family: var(--font-mono);
      font-size: 0.84rem;
      color: var(--text-secondary);
    }

    .status-pill {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 5px 10px;
      border-radius: var(--radius-pill);
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      width: fit-content;
    }

    .status-pill .dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
    }

    .status-boarding {
      background: rgba(56, 242, 209, 0.12);
      color: var(--neon-cyan);
      border: 1px solid rgba(56, 242, 209, 0.3);
    }
    .status-boarding .dot { background: var(--neon-cyan); box-shadow: 0 0 8px var(--neon-cyan); }

    .status-ontime {
      background: rgba(230, 184, 119, 0.11);
      color: var(--sand-bright);
      border: 1px solid rgba(230, 184, 119, 0.28);
    }
    .status-ontime .dot { background: var(--sand-bright); }

    .status-limited {
      background: rgba(255, 63, 130, 0.12);
      color: #ff7ba9;
      border: 1px solid rgba(255, 63, 130, 0.3);
    }
    .status-limited .dot { background: var(--neon-rose); }

    .row-book-btn {
      padding: 8px 14px;
      border-radius: var(--radius-pill);
      border: 1px solid var(--border-subtle);
      background: rgba(255, 255, 255, 0.03);
      font-size: 0.8rem;
      font-weight: 500;
      color: var(--text-primary);
      transition: all 0.2s ease;
      justify-self: end;
    }

    .row-book-btn:hover {
      background: var(--sand-gold);
      border-color: var(--sand-gold);
      color: #120d06;
    }

    .timetable-note {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 12px;
      padding: 16px 28px;
      background: rgba(255, 255, 255, 0.015);
      border-top: 1px solid var(--border-subtle);
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--text-muted);
    }

    /* Pricing Section */
    .billing-toggle {
      display: inline-flex;
      align-items: center;
      padding: 4px;
      border-radius: var(--radius-pill);
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      gap: 4px;
    }

    .toggle-btn {
      padding: 8px 16px;
      border-radius: var(--radius-pill);
      font-size: 0.82rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: all 0.22s ease;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .toggle-btn.active {
      background: rgba(230, 184, 119, 0.16);
      color: var(--sand-bright);
      box-shadow: inset 0 0 0 1px rgba(230, 184, 119, 0.35);
    }

    .save-tag {
      font-family: var(--font-mono);
      font-size: 0.65rem;
      padding: 2px 6px;
      border-radius: 4px;
      background: rgba(56, 242, 209, 0.14);
      color: var(--neon-cyan);
    }

    .pricing-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 26px;
      align-items: stretch;
    }

    .price-card {
      position: relative;
      display: flex;
      flex-direction: column;
      padding: 36px 32px 34px;
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, rgba(19, 22, 36, 0.9) 0%, rgba(11, 13, 22, 0.96) 100%);
      border: 1px solid var(--border-subtle);
      transition: transform 0.25s ease, border-color 0.25s ease;
    }

    .price-card:hover {
      transform: translateY(-4px);
    }

    .price-card.featured {
      background: linear-gradient(180deg, rgba(28, 26, 42, 0.96) 0%, rgba(14, 16, 28, 0.98) 100%);
      border: 1px solid rgba(230, 184, 119, 0.45);
      box-shadow:
        0 28px 70px rgba(0, 0, 0, 0.55),
        0 0 50px rgba(230, 184, 119, 0.1);
    }

    .featured-ribbon {
      position: absolute;
      top: -12px;
      right: 28px;
      padding: 5px 12px;
      border-radius: var(--radius-pill);
      background: linear-gradient(90deg, var(--sand-gold), var(--sand-bright));
      color: #140e06;
      font-family: var(--font-mono);
      font-size: 0.66rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .tier-class {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--sand-gold);
      margin-bottom: 10px;
    }

    .tier-name {
      font-size: 1.5rem;
      font-weight: 600;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      margin-bottom: 10px;
    }

    .tier-desc {
      font-size: 0.9rem;
      color: var(--text-secondary);
      line-height: 1.6;
      min-height: 46px;
      margin-bottom: 26px;
    }

    .tier-price-row {
      display: flex;
      align-items: baseline;
      gap: 8px;
      padding-bottom: 24px;
      margin-bottom: 24px;
      border-bottom: 1px solid var(--border-subtle);
    }

    .tier-price {
      font-family: var(--font-mono);
      font-size: 2.55rem;
      font-weight: 600;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      line-height: 1;
    }

    .tier-period {
      font-size: 0.82rem;
      color: var(--text-muted);
    }

    .tier-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 13px;
      margin-bottom: 32px;
      flex: 1;
    }

    .tier-list li {
      display: flex;
      align-items: flex-start;
      gap: 11px;
      font-size: 0.9rem;
      color: var(--text-secondary);
      line-height: 1.48;
    }

    .check-icon {
      width: 17px;
      height: 17px;
      flex-shrink: 0;
      margin-top: 2px;
      color: var(--sand-gold);
    }

    .price-card.featured .check-icon {
      color: var(--neon-cyan);
    }

    .price-card .btn {
      width: 100%;
    }

    /* Testimonial Section */
    .testimonial-wrap {
      position: relative;
      border-radius: 24px;
      padding: 58px 64px;
      background:
        radial-gradient(circle at 92% 18%, rgba(56, 242, 209, 0.1), transparent 40%),
        radial-gradient(circle at 8% 85%, rgba(230, 184, 119, 0.1), transparent 45%),
        linear-gradient(135deg, rgba(20, 23, 38, 0.92) 0%, rgba(11, 13, 23, 0.96) 100%);
      border: 1px solid rgba(230, 184, 119, 0.22);
      overflow: hidden;
      box-shadow: var(--shadow-card);
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 260px;
      gap: 48px;
      align-items: center;
    }

    .quote-mark {
      font-family: var(--font-serif);
      font-size: 4.5rem;
      line-height: 0.6;
      color: var(--sand-gold);
      opacity: 0.45;
      margin-bottom: 18px;
      display: block;
    }

    .testimonial-quote {
      font-family: var(--font-serif);
      font-size: clamp(1.35rem, 2.2vw, 1.82rem);
      font-style: italic;
      line-height: 1.5;
      color: var(--text-primary);
      margin-bottom: 28px;
      letter-spacing: -0.005em;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .author-avatar {
      width: 50px;
      height: 50px;
      border-radius: 50%;
      flex-shrink: 0;
      border: 1px solid rgba(230, 184, 119, 0.4);
      overflow: hidden;
    }

    .author-name {
      font-weight: 600;
      font-size: 0.98rem;
      color: var(--text-primary);
    }

    .author-role {
      font-size: 0.84rem;
      color: var(--text-secondary);
      margin-top: 2px;
    }

    .ticket-stub {
      padding: 22px 20px;
      border-radius: 14px;
      background: rgba(7, 9, 16, 0.72);
      border: 1px dashed rgba(230, 184, 119, 0.32);
      font-family: var(--font-mono);
    }

    .stub-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 0.66rem;
      letter-spacing: 0.14em;
      color: var(--neon-cyan);
      text-transform: uppercase;
      padding-bottom: 12px;
      margin-bottom: 14px;
      border-bottom: 1px solid var(--border-subtle);
    }

    .stub-row {
      display: flex;
      justify-content: space-between;
      font-size: 0.74rem;
      margin-bottom: 9px;
    }

    .stub-row span:first-child {
      color: var(--text-muted);
    }

    .stub-row span:last-child {
      color: var(--text-primary);
      font-weight: 600;
    }

    .stub-stars {
      display: flex;
      gap: 4px;
      margin-top: 14px;
      padding-top: 12px;
      border-top: 1px solid var(--border-subtle);
      color: var(--sand-bright);
      font-size: 0.85rem;
      align-items: center;
      justify-content: space-between;
    }

    .stub-stars small {
      color: var(--text-muted);
      font-size: 0.66rem;
    }

    /* Footer */
    .footer {
      border-top: 1px solid var(--border-subtle);
      background: #06070c;
      padding: 72px 0 38px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr 1.35fr;
      gap: 44px;
      padding-bottom: 52px;
      border-bottom: 1px solid var(--border-subtle);
    }

    .footer-tagline {
      margin-top: 16px;
      font-size: 0.9rem;
      color: var(--text-secondary);
      max-width: 300px;
      line-height: 1.65;
    }

    .footer-coords {
      margin-top: 18px;
      font-family: var(--font-mono);
      font-size: 0.7rem;
      letter-spacing: 0.1em;
      color: var(--text-muted);
    }

    .footer-col h4 {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--sand-gold);
      margin-bottom: 18px;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 11px;
    }

    .footer-links a {
      font-size: 0.88rem;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .footer-links a:hover {
      color: var(--text-primary);
    }

    .dispatch-form {
      display: flex;
      gap: 8px;
      margin-top: 14px;
    }

    .dispatch-input {
      flex: 1;
      min-width: 0;
      padding: 11px 14px;
      border-radius: var(--radius-pill);
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--border-subtle);
      color: var(--text-primary);
      font-size: 0.86rem;
      outline: none;
      transition: border-color 0.2s ease;
    }

    .dispatch-input:focus {
      border-color: var(--sand-gold);
    }

    .dispatch-msg {
      margin-top: 10px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--neon-cyan);
      min-height: 18px;
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
      padding-top: 28px;
      font-size: 0.8rem;
      color: var(--text-muted);
    }

    .footer-bottom-right {
      display: flex;
      gap: 24px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
    }

    /* Reservation Modal */
    .modal-backdrop {
      position: fixed;
      inset: 0;
      z-index: 200;
      background: rgba(4, 5, 10, 0.78);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }

    .modal-backdrop.open {
      display: flex;
    }

    .modal-card {
      width: 100%;
      max-width: 540px;
      border-radius: 20px;
      background: linear-gradient(180deg, #15192a 0%, #0d101c 100%);
      border: 1px solid rgba(230, 184, 119, 0.3);
      box-shadow: 0 32px 90px rgba(0, 0, 0, 0.75);
      padding: 32px;
      position: relative;
      max-height: 92vh;
      overflow-y: auto;
    }

    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 16px;
      margin-bottom: 24px;
    }

    .modal-title {
      font-size: 1.45rem;
      font-weight: 600;
      letter-spacing: -0.02em;
      margin-top: 6px;
    }

    .modal-close {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      border: 1px solid var(--border-subtle);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      transition: all 0.2s ease;
    }

    .modal-close:hover {
      border-color: var(--sand-gold);
      color: var(--text-primary);
    }

    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      margin-bottom: 20px;
    }

    .form-field {
      display: flex;
      flex-direction: column;
      gap: 7px;
    }

    .form-field.full {
      grid-column: 1 / -1;
    }

    .form-field label {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-secondary);
    }

    .form-control {
      width: 100%;
      padding: 11px 14px;
      border-radius: 10px;
      background: rgba(7, 9, 16, 0.75);
      border: 1px solid var(--border-subtle);
      color: var(--text-primary);
      font-size: 0.92rem;
      outline: none;
      transition: border-color 0.2s ease;
    }

    .form-control:focus {
      border-color: var(--sand-gold);
    }

    .summary-box {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 16px 18px;
      border-radius: 12px;
      background: rgba(230, 184, 119, 0.07);
      border: 1px solid rgba(230, 184, 119, 0.22);
      margin-bottom: 22px;
    }

    .summary-label {
      font-size: 0.82rem;
      color: var(--text-secondary);
    }

    .summary-total {
      font-family: var(--font-mono);
      font-size: 1.55rem;
      font-weight: 600;
      color: var(--sand-bright);
    }

    .boarding-pass {
      display: none;
      padding: 24px;
      border-radius: 16px;
      background: rgba(7, 9, 16, 0.85);
      border: 1px solid rgba(56, 242, 209, 0.35);
    }

    .boarding-pass.visible {
      display: block;
    }

    .pass-top {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 16px;
      margin-bottom: 16px;
      border-bottom: 1px dashed rgba(245, 236, 223, 0.18);
    }

    .pass-codes {
      display: flex;
      align-items: center;
      gap: 14px;
      font-family: var(--font-mono);
      font-size: 1.5rem;
      font-weight: 700;
    }

    .pass-arrow {
      color: var(--sand-gold);
      font-size: 1rem;
    }

    .pass-meta-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
      font-family: var(--font-mono);
      font-size: 0.76rem;
      margin-bottom: 18px;
    }

    .pass-meta-grid span {
      display: block;
      color: var(--text-muted);
      font-size: 0.65rem;
      text-transform: uppercase;
      margin-bottom: 2px;
    }

    /* Mobile Drawer */
    .mobile-menu {
      display: none;
      border-top: 1px solid var(--border-subtle);
      padding: 18px 32px 24px;
      background: rgba(7, 8, 13, 0.96);
    }

    .mobile-menu.open {
      display: block;
    }

    .mobile-menu ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 14px;
      margin-bottom: 18px;
    }

    .mobile-menu a {
      font-size: 1rem;
      color: var(--text-primary);
    }

    /* Responsive Breakpoints */
    @media (max-width: 1120px) {
      .hero-grid {
        grid-template-columns: 1fr;
        gap: 44px;
      }

      .hero-copy {
        max-width: 640px;
      }

      .timetable-head {
        display: none;
      }

      .timetable-row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 12px 18px;
        padding: 20px 24px;
      }

      .row-book-btn {
        justify-self: start;
        grid-column: 1 / -1;
        margin-top: 4px;
      }
    }

    @media (max-width: 960px) {
      .nav-links,
      .nav-status {
        display: none;
      }

      .nav-toggle {
        display: inline-flex;
      }

      .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
        margin-bottom: 38px;
      }

      .features-grid,
      .pricing-grid {
        grid-template-columns: 1fr;
      }

      .testimonial-wrap {
        padding: 38px 28px;
      }

      .testimonial-grid {
        grid-template-columns: 1fr;
        gap: 30px;
      }

      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 640px) {
      .container {
        padding: 0 20px;
      }

      .hero {
        padding: 36px 0 64px;
      }

      section.band {
        padding: 68px 0;
      }

      .telemetry-bar {
        position: static;
        border-radius: 0;
        border: none;
        border-top: 1px solid var(--border-subtle);
        flex-direction: column;
        align-items: flex-start;
        gap: 6px;
      }

      .hero-metrics {
        grid-template-columns: repeat(3, 1fr);
        gap: 10px;
      }

      .metric-val {
        font-size: 1.05rem;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .form-grid {
        grid-template-columns: 1fr;
      }

      .nav-actions .btn-primary {
        padding: 10px 16px;
        font-size: 0.82rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>

  <!-- Navigation Bar -->
  <header class="navbar">
    <div class="container nav-inner">
      <a href="#top" class="brand" aria-label="Dune Line Home">
        <svg class="brand-mark" viewBox="0 0 36 36" fill="none" aria-hidden="true">
          <rect x="1" y="1" width="34" height="34" rx="9" fill="#121524" stroke="rgba(230,184,119,0.45)" stroke-width="1.2"/>
          <path d="M5 24.5C10.5 18.5 16 17.5 22 20.5C26 22.5 29 21.8 31.5 19.5" stroke="#E6B877" stroke-width="1.7" stroke-linecap="round"/>
          <path d="M6.5 27.5H29.5" stroke="#38F2D1" stroke-width="1.4" stroke-linecap="round"/>
          <path d="M23 14.5V9.5M26.5 15.5V7.5M29.5 15.5V11" stroke="#FF3F82" stroke-width="1.5" stroke-linecap="round"/>
          <circle cx="11.5" cy="11.5" r="2.6" fill="#F7D59C"/>
        </svg>
        <div class="brand-text">
          <span class="brand-name">Dune Line</span>
          <span class="brand-sub">OCH → VSP Rail</span>
        </div>
      </a>

      <nav aria-label="Primary Navigation">
        <ul class="nav-links">
          <li><a href="#experience">Experience</a></li>
          <li><a href="#timetable">Timetable</a></li>
          <li><a href="#fares">Fares</a></li>
          <li><a href="#journal">Passenger Note</a></li>
        </ul>
      </nav>

      <div class="nav-actions">
        <div class="nav-status" title="Next scheduled overnight departure">
          <span class="pulse-dot" aria-hidden="true"></span>
          <span>NEXT DL-04 <strong>21:40</strong></span>
        </div>
        <button class="btn btn-primary" type="button" data-open-booking>Reserve Cabin</button>
        <button class="nav-toggle" type="button" id="mobileMenuBtn" aria-label="Toggle Menu" aria-expanded="false">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round">
            <path d="M3 6h14M3 10h14M3 14h14"/>
          </svg>
        </button>
      </div>
    </div>

    <div class="mobile-menu" id="mobileMenu">
      <ul>
        <li><a href="#experience">Experience</a></li>
        <li><a href="#timetable">Timetable</a></li>
        <li><a href="#fares">Fares</a></li>
        <li><a href="#journal">Passenger Note</a></li>
      </ul>
      <div class="nav-status" style="display:inline-flex;">
        <span class="pulse-dot" aria-hidden="true"></span>
        <span>NEXT DL-04 <strong>21:40</strong> • OCHRE BASIN</span>
      </div>
    </div>
  </header>

  <main id="top">
    <!-- Hero Section -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <div class="hero-badge">
            <span class="eyebrow-dot" aria-hidden="true"></span>
            Overnight Trans-Desert Sleeper
          </div>

          <h1 class="hero-title">
            Sleep through the dunes.
            <span class="serif-accent">Wake in the neon.</span>
          </h1>

          <p class="hero-lead">
            Board at Ochre Basin under a cooling desert dusk and glide 840 kilometers across the starlit Glass Erg. Arrive directly inside Vespera’s electric sky-concourse at dawn—rested, unhurried, and worlds apart.
          </p>

          <div class="hero-ctas">
            <button class="btn btn-primary" type="button" data-open-booking>
              Book Tonight’s Crossing
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="M3.5 8h9M8.5 4l4 4-4 4"/>
              </svg>
            </button>
            <a class="btn btn-secondary" href="#timetable">View Timetable</a>
          </div>

          <div class="hero-metrics">
            <div>
              <div class="metric-val">840<span>KM</span></div>
              <div class="metric-label">Glass Erg Crossing</div>
            </div>
            <div>
              <div class="metric-val">8H 35<span>M</span></div>
              <div class="metric-label">Dusk to Neon Dawn</div>
            </div>
            <div>
              <div class="metric-val">28<span>dB</span></div>
              <div class="metric-label">Cabin Acoustic Floor</div>
            </div>
          </div>
        </div>

        <!-- Bespoke Code-Drawn Hero Illustration -->
        <div class="hero-visual">
          <div class="artwork-frame">
            <svg class="artwork-svg" viewBox="0 0 760 540" fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustration of the Dune Line overnight sleeper train gliding across starlit desert dunes toward the distant glowing neon skyline of Vespera City">
              <defs>
                <!-- Night Desert Sky -->
                <linearGradient id="skyGrad" x1="380" y1="0" x2="380" y2="380" gradientUnits="userSpaceOnUse">
                  <stop offset="0%" stop-color="#070812"/>
                  <stop offset="46%" stop-color="#121226"/>
                  <stop offset="78%" stop-color="#281632"/>
                  <stop offset="100%" stop-color="#401c3a"/>
                </linearGradient>

                <!-- Neon City Horizon Glow -->
                <radialGradient id="cityGlowCyan" cx="76%" cy="58%" r="36%">
                  <stop offset="0%" stop-color="#38F2D1" stop-opacity="0.34"/>
                  <stop offset="50%" stop-color="#8C52FF" stop-opacity="0.16"/>
                  <stop offset="100%" stop-color="#070812" stop-opacity="0"/>
                </radialGradient>

                <radialGradient id="cityGlowRose" cx="62%" cy="61%" r="28%">
                  <stop offset="0%" stop-color="#FF3F82" stop-opacity="0.32"/>
                  <stop offset="60%" stop-color="#FF3F82" stop-opacity="0.08"/>
                  <stop offset="100%" stop-color="#070812" stop-opacity="0"/>
                </radialGradient>

                <!-- Moon Glow -->
                <radialGradient id="moonGlow" cx="50%" cy="50%" r="50%">
                  <stop offset="0%" stop-color="#F7D59C" stop-opacity="0.45"/>
                  <stop offset="100%" stop-color="#F7D59C" stop-opacity="0"/>
                </radialGradient>

                <!-- Vertical Neon Sky Beams -->
                <linearGradient id="beamCyan" x1="0" y1="1" x2="0" y2="0">
