  <script>
    (function () {
      const TIER_PRICES = {
        "Nomad Berth": { oneway: 210, roundtrip: 355 },
        "Mirage Suite": { oneway: 460, roundtrip: 780 },
        "Sovereign Observatory": { oneway: 940, roundtrip: 1590 }
      };

      let currentTripType = "oneway";

      // Mobile Navigation Toggle
      const mobileBtn = document.getElementById("mobileMenuBtn");
      const mobileMenu = document.getElementById("mobileMenu");
      if (mobileBtn && mobileMenu) {
        mobileBtn.addEventListener("click", () => {
          const isOpen = mobileMenu.classList.toggle("open");
          mobileBtn.setAttribute("aria-expanded", String(isOpen));
        });
        mobileMenu.querySelectorAll("a").forEach((link) => {
          link.addEventListener("click", () => {
            mobileMenu.classList.remove("open");
            mobileBtn.setAttribute("aria-expanded", "false");
          });
        });
      }

      // Pricing One-Way / Round-Trip Toggle
      const toggleButtons = document.querySelectorAll(".toggle-btn");
      const priceEls = document.querySelectorAll(".tier-price");
      const periodEls = document.querySelectorAll("[data-period-label]");

      function setTripType(trip) {
        currentTripType = trip;
        toggleButtons.forEach((btn) => {
          btn.classList.toggle("active", btn.dataset.trip === trip);
        });
        priceEls.forEach((el) => {
          const amount = trip === "roundtrip" ? el.dataset.priceRoundtrip : el.dataset.priceOneway;
          el.textContent = "$" + Number(amount).toLocaleString();
        });
        periodEls.forEach((el) => {
          el.textContent = trip === "roundtrip" ? "round-trip" : "per crossing";
        });
      }

      toggleButtons.forEach((btn) => {
        btn.addEventListener("click", () => setTripType(btn.dataset.trip));
      });

      // Reservation Modal Logic
      const modal = document.getElementById("bookingModal");
      const closeModalBtn = document.getElementById("closeModalBtn");
      const bookingForm = document.getElementById("bookingForm");
      const boardingPass = document.getElementById("boardingPass");
      const resetBookingBtn = document.getElementById("resetBookingBtn");

      const trainSelect = document.getElementById("trainSelect");
      const tierSelect = document.getElementById("tierSelect");
      const tripSelect = document.getElementById("tripSelect");
      const guestsSelect = document.getElementById("guestsSelect");
      const passengerName = document.getElementById("passengerName");
      const summaryDesc = document.getElementById("summaryDesc");
      const summaryTotal = document.getElementById("summaryTotal");

      function updateBookingSummary() {
        const tier = tierSelect.value;
        const trip = tripSelect.value;
        const guests = Number(guestsSelect.value);
        const unit = TIER_PRICES[tier][trip];
        const total = unit * guests;
        const tripLabel = trip === "roundtrip" ? "Round-Trip" : "One-Way";
        const guestLabel = guests === 1 ? "1 Passenger" : guests + " Passengers";
        summaryDesc.textContent = tier + " • " + tripLabel + " • " + guestLabel;
        summaryTotal.textContent = "$" + total.toLocaleString();
      }

      function openBookingModal(opts) {
        bookingForm.style.display = "block";
        boardingPass.classList.remove("visible");

        if (opts && opts.train) {
          trainSelect.value = opts.train;
        }
        if (opts && opts.tier) {
          tierSelect.value = opts.tier;
        }
        tripSelect.value = currentTripType;
        updateBookingSummary();

        modal.classList.add("open");
        document.body.style.overflow = "hidden";
      }

      function closeBookingModal() {
        modal.classList.remove("open");
        document.body.style.overflow = "";
      }

      document.querySelectorAll("[data-open-booking]").forEach((trigger) => {
        trigger.addEventListener("click", (e) => {
          e.preventDefault();
          openBookingModal({
            train: trigger.dataset.train,
            tier: trigger.dataset.tier
          });
        });
      });

      [tierSelect, tripSelect, guestsSelect].forEach((el) => {
        el.addEventListener("change", updateBookingSummary);
      });

      closeModalBtn.addEventListener("click", closeBookingModal);
      modal.addEventListener("click", (e) => {
        if (e.target === modal) closeBookingModal();
      });

      document.addEventListener("keydown", (e) => {
        if (e.key === "Escape" && modal.classList.contains("open")) {
          closeBookingModal();
        }
      });

      bookingForm.addEventListener("submit", (e) => {
        e.preventDefault();
        const name = passengerName.value.trim() || "Valued Traveler";
        const codeNum = Math.floor(1000 + Math.random() * 9000);

        document.getElementById("passPassenger").textContent = name.toUpperCase();
        document.getElementById("passCode").textContent = "DL-" + codeNum + "-VSP";
        document.getElementById("passService").textContent = trainSelect.value.split("•")[0].trim() + " / " + trainSelect.value.match(/\(([^)]+)\)/)[1];
        document.getElementById("passCabin").textContent = tierSelect.value.toUpperCase() + " ×" + guestsSelect.value;

        bookingForm.style.display = "none";
        boardingPass.classList.add("visible");
      });

      resetBookingBtn.addEventListener("click", () => {
        bookingForm.reset();
        tripSelect.value = currentTripType;
        updateBookingSummary();
        boardingPass.classList.remove("visible");
        bookingForm.style.display = "block";
      });

      // Footer Dispatch Newsletter Form
      const dispatchForm = document.getElementById("dispatchForm");
      const dispatchEmail = document.getElementById("dispatchEmail");
      const dispatchMsg = document.getElementById("dispatchMsg");

      dispatchForm.addEventListener("submit", (e) => {
        e.preventDefault();
        const email = dispatchEmail.value.trim();
        if (!email) return;
        dispatchMsg.textContent = "SIGNAL LOCKED — NIGHT DISPATCH REGISTERED FOR " + email.toUpperCase();
        dispatchEmail.value = "";
      });
    })();
  </script>
</body>
</html>
